1	// Parse Entire checkpoints into Session rows. See docs/DESIGN.md §"Entire checkpoint format" and §"Ingest".
2	import { createHash } from "node:crypto";
3	import { basename } from "node:path";
4	import type { Session, SessionSource } from "../types";
5	
6	export type Backend = SessionSource | "auto";
7	
8	/** Where tokens and model came from. Session.source is the storage backend, so this lives beside it. */
9	export type UsageSource = "metadata" | "transcript" | "none";
10	
11	export interface ParsedSession extends Session {
12	  usage_source: UsageSource;
13	  model_source: "metadata" | "transcript" | "none";
14	}
15	
16	export interface ParseOptions {
17	  warn?: (msg: string) => void;
18	}
