20	const BRANCH_REFS = ["refs/heads/entire/checkpoints/v1", "refs/remotes/origin/entire/checkpoints/v1"];
21	const PROMPT_SEP = "\n\n---\n\n";
22	
23	function git(repo: string, args: string[]): string | null {
24	  const p = Bun.spawnSync(["git", ...args], { cwd: repo, stdout: "pipe", stderr: "pipe" });
25	  return p.exitCode === 0 ? p.stdout.toString() : null;
26	}
