28	/** A checkpoint's files, keyed by path relative to the checkpoint root. */
29	interface RawCheckpoint {
30	  id: string;
31	  source: SessionSource;
32	  read: (path: string) => string | null;
33	  paths: string[];
34	}
35	
36	function makeReader(repo: string, treeish: string, prefix: string) {
37	  return (path: string) => git(repo, ["show", `${treeish}:${prefix}${path}`]);
38	}
39	
40	function listBranch(repo: string): RawCheckpoint[] {
41	  for (const ref of BRANCH_REFS) {
42	    const out = git(repo, ["ls-tree", "-r", "--name-only", ref]);
43	    if (!out) continue;
44	    const byId = new Map<string, string[]>();
45	    for (const p of out.split("\n").filter(Boolean)) {
46	      const m = /^([0-9a-f]{2})\/([^/]+)\/(.+)$/.exec(p);
47	      if (!m) continue;
48	      const id = m[1]! + m[2]!;
49	      (byId.get(id) ?? byId.set(id, []).get(id)!).push(m[3]!);
50	    }
51	    if (byId.size === 0) continue;
52	    return [...byId].map(([id, paths]) => ({
53	      id,
54	      source: "branch" as const,
55	      paths,
56	      read: makeReader(repo, ref, `${id.slice(0, 2)}/${id.slice(2)}/`),
57	    }));
58	  }
59	  return [];
60	}
61	
62	function listRefs(repo: string): RawCheckpoint[] {
63	  const out = git(repo, ["for-each-ref", "--format=%(refname)", "refs/entire/checkpoints/"]);
64	  if (!out) return [];
65	  const res: RawCheckpoint[] = [];
66	  for (const ref of out.split("\n").filter(Boolean)) {
67	    const tree = git(repo, ["ls-tree", "-r", "--name-only", ref]);
68	    if (tree === null) continue;
69	    res.push({
70	      id: ref.split("/").pop()!,
71	      source: "git-refs",
72	      paths: tree.split("\n").filter(Boolean),
73	      read: makeReader(repo, ref, ""),
74	    });
75	  }
76	  return res;
77	}
