79	/** checkpoint id → [commit sha, unix time] of the earliest commit carrying its trailer, on any branch. */
80	function mapCommits(repo: string): Map<string, string> {
81	  const out = git(repo, ["log", "--all", "--format=%H%x1f%ct%x1f%(trailers:key=Entire-Checkpoint,valueonly,separator=%x2c)%x1e"]);
82	  const best = new Map<string, { sha: string; t: number }>();
83	  for (const rec of (out ?? "").split("\x1e")) {
84	    const [sha, ct, ids] = rec.trim().split("\x1f");
85	    if (!sha || !ids) continue;
86	    for (const id of ids.split(",").map((s) => s.trim()).filter(Boolean)) {
87	      const t = Number(ct);
88	      const cur = best.get(id);
89	      if (!cur || t < cur.t) best.set(id, { sha, t });
90	    }
91	  }
92	  return new Map([...best].map(([id, v]) => [id, v.sha]));
93	}
