101	type Json = Record<string, any>;
102	
103	function jsonl(text: string | null): Json[] {
104	  if (!text) return [];
105	  const rows: Json[] = [];
106	  for (const line of text.split("\n")) {
107	    if (!line.trim()) continue;
108	    try {
109	      rows.push(JSON.parse(line));
110	    } catch {
111	      // transcripts are best-effort; skip torn lines
112	    }
113	  }
114	  return rows;
115	}
