117	const cleanModel = (m: string) => m.replace(/\[[^\]]*\]$/, "");
118	const hashRules = (s: string) => createHash("sha256").update(s.replace(/\r\n/g, "\n").trim()).digest("hex");
119	
120	interface TranscriptInfo {
121	  model: string | null;
122	  rules_hash: string | null;
123	  tokens: { in: number; out: number; cr: number; cw: number } | null;
124	  prompts: string[];
125	  first_ts: string | null;
126	  last_ts: string | null;
127	}
128	
129	function readTranscript(rows: Json[]): TranscriptInfo {
130	  let model: string | null = null;
131	  let attachedModel: string | null = null;
132	  let rules: string | null = null;
133	  const sum = { in: 0, out: 0, cr: 0, cw: 0 };
134	  let sawClaudeUsage = false;
135	  let codexTotal: Json | null = null;
136	  const prompts: string[] = [];
137	  const ts: string[] = [];
138	
139	  for (const r of rows) {
140	    if (typeof r.timestamp === "string") ts.push(r.timestamp);
141	    if (r.type === "attachment") {
142	      const a = r.attachment ?? {};
143	      if (a.type === "model" && a.identity?.modelId) attachedModel ??= cleanModel(String(a.identity.modelId));
144	      if (a.type === "instructions" && rules === null) {
145	        const proj = (a.files ?? []).filter((f: Json) => f.type === "Project" && typeof f.content === "string");
146	        if (proj.length) rules = hashRules(proj.map((f: Json) => f.content).join("\n"));
147	      }
148	    } else if (r.type === "assistant" && r.message) {
149	      if (typeof r.message.model === "string" && r.message.model && r.message.model !== "<synthetic>") model ??= r.message.model;
150	      const u = r.message.usage;
151	      if (u) {
152	        sawClaudeUsage = true;
153	        sum.in += u.input_tokens ?? 0;
154	        sum.out += u.output_tokens ?? 0;
155	        sum.cr += u.cache_read_input_tokens ?? 0;
156	        sum.cw += u.cache_creation_input_tokens ?? 0;
157	      }
158	    } else if (r.type === "user" && r.message && !r.isMeta && !r.isSidechain) {
159	      // tool results and approvals arrive as user rows holding tool_result blocks; they are not prompts
160	      const c = r.message.content;
161	      const text =
162	        typeof c === "string"
163	          ? c
164	          : Array.isArray(c) && !c.some((b: Json) => b.type === "tool_result")
165	            ? c.filter((b: Json) => b.type === "text").map((b: Json) => b.text).join("\n")
166	            : "";
167	      if (text.trim()) prompts.push(text.trim());
168	    } else if (r.type === "turn_context") {
169	      if (typeof r.payload?.model === "string" && r.payload.model) model ??= r.payload.model;
170	    } else if (r.type === "world_state") {
171	      const md = r.payload?.state?.agents_md;
172	      if (rules === null && typeof md === "string" && md) rules = hashRules(md);
173	    } else if (r.type === "event_msg") {
174	      const p = r.payload ?? {};
175	      if (p.type === "token_count" && p.info?.total_token_usage) codexTotal = p.info.total_token_usage;
176	      if (p.type === "user_message" && typeof p.message === "string" && p.message.trim()) prompts.push(p.message.trim());
177	    }
178	  }
179	
180	  let tokens: TranscriptInfo["tokens"] = null;
181	  if (sawClaudeUsage) tokens = sum;
182	  else if (codexTotal) {
183	    const cached = codexTotal.cached_input_tokens ?? 0;
184	    tokens = {
185	      in: Math.max(0, (codexTotal.input_tokens ?? 0) - cached), // Entire's input excludes cached input
186	      out: codexTotal.output_tokens ?? 0,
187	      cr: cached,
188	      cw: codexTotal.cache_write_input_tokens ?? 0,
189	    };
190	  }
191	  ts.sort();
192	  return { model: attachedModel ?? model, rules_hash: rules, tokens, prompts, first_ts: ts[0] ?? null, last_ts: ts.at(-1) ?? null };
193	}
