195	/** One session's slice inside one checkpoint. */
196	interface Slice {
197	  session_id: string;
198	  checkpoint_id: string;
199	  source: SessionSource;
200	  agent: string;
201	  model: string | null;
202	  model_from_meta: boolean;
203	  rules_hash: string | null;
204	  tokens: { in: number; out: number; cr: number; cw: number } | null;
205	  usage_source: UsageSource;
206	  prompts: string[];
207	  files: string[];
208	  start: string;
209	  end: string;
210	}
211	
212	function parseCheckpoint(cp: RawCheckpoint): Slice[] {
213	  const need = (path: string): Json => {
214	    const t = cp.read(path);
215	    if (t === null) throw new Error(`missing ${path}`);
216	    return JSON.parse(t);
217	  };
218	  const root = need("metadata.json");
219	  const indices = new Set<string>();
220	  for (const p of cp.paths) {
221	    const m = /^(\d+)\/metadata\.json$/.exec(p);
222	    if (m) indices.add(m[1]!);
223	  }
224	  if (indices.size === 0) throw new Error("no session metadata");
225	  const ordered = [...indices].sort((a, b) => Number(a) - Number(b));
226	
227	  // subagent transcripts: attach to the parent session (the only/first session of the checkpoint)
228	  const taskRows = cp.paths
229	    .filter((p) => /^tasks\/[^/]+\/agent-[^/]+\.jsonl$/.test(p))
230	    .flatMap((p) => jsonl(cp.read(p)));
231	
232	  const slices: Slice[] = [];
233	  ordered.forEach((n, i) => {
234	    const meta = need(`${n}/metadata.json`);
235	    if (typeof meta.session_id !== "string" || !meta.session_id) throw new Error(`${n}/metadata.json has no session_id`);
236	    const hasTranscript = cp.paths.includes(`${n}/full.jsonl`);
237	    const tr = readTranscript(jsonl(hasTranscript ? cp.read(`${n}/full.jsonl`) : null));
238	    const promptTxt = cp.paths.includes(`${n}/prompt.txt`) ? cp.read(`${n}/prompt.txt`) : null;
239	    const prompts = promptTxt !== null ? promptTxt.split(PROMPT_SEP).map((s) => s.trim()).filter(Boolean) : tr.prompts;
240	
241	    const mu = meta.token_usage;
242	    let tokens: Slice["tokens"] = null;
243	    let usage_source: UsageSource = "none";
244	    if (mu && typeof mu === "object") {
245	      tokens = { in: mu.input_tokens ?? 0, out: mu.output_tokens ?? 0, cr: mu.cache_read_tokens ?? 0, cw: mu.cache_creation_tokens ?? 0 };
246	      usage_source = "metadata";
247	    } else if (tr.tokens) {
248	      tokens = { ...tr.tokens };
249	      usage_source = "transcript";
250	      if (i === 0 && taskRows.length) {
251	        const sub = readTranscript(taskRows).tokens;
252	        if (sub) {
253	          tokens.in += sub.in;
254	          tokens.out += sub.out;
255	          tokens.cr += sub.cr;
256	          tokens.cw += sub.cw;
257	        }
258	      }
259	    }
260	    const created = typeof meta.created_at === "string" ? meta.created_at : "";
261	    slices.push({
262	      session_id: meta.session_id,
263	      checkpoint_id: String(meta.checkpoint_id ?? root.checkpoint_id ?? cp.id),
264	      source: cp.source,
265	      agent: String(meta.agent ?? "unknown"),
266	      model: typeof meta.model === "string" && meta.model ? meta.model : tr.model,
267	      model_from_meta: typeof meta.model === "string" && !!meta.model,
268	      rules_hash: tr.rules_hash,
269	      tokens,
270	      usage_source,
271	      prompts,
272	      files: Array.isArray(meta.files_touched) ? meta.files_touched.map(String) : [],
273	      start: [created, tr.first_ts].filter(Boolean).sort()[0] ?? "",
274	      end: [created, tr.last_ts].filter(Boolean).sort().at(-1) ?? "",
275	    });
276	  });
277	  return slices;
278	}
