280	/** Parse every checkpoint in `repoPath` into one Session per agent session id. */
281	export function parseCheckpoints(repoPath: string, backend: Backend = "auto", opts: ParseOptions = {}): ParsedSession[] {
282	  const warn = opts.warn ?? ((m: string) => console.warn(m));
283	  let cps: RawCheckpoint[] = [];
284	  if (backend === "branch" || backend === "auto") cps = listBranch(repoPath);
285	  if (backend === "git-refs" || (backend === "auto" && cps.length === 0)) cps = cps.concat(listRefs(repoPath));
286	
287	  const commits = mapCommits(repoPath);
288	  const gh = githubUrlBase(repoPath);
289	  const repoName = gh ? `${gh.owner}/${gh.name}` : basename(repoPath);
290	
291	  const slices: Slice[] = [];
292	  for (const cp of cps.sort((a, b) => a.id.localeCompare(b.id))) {
293	    try {
294	      slices.push(...parseCheckpoint(cp));
295	    } catch (e) {
296	      warn(`skipping checkpoint ${cp.id}: ${(e as Error).message}`);
297	    }
298	  }
299	
300	  const bySession = new Map<string, Slice[]>();
301	  for (const s of slices) (bySession.get(s.session_id) ?? bySession.set(s.session_id, []).get(s.session_id)!).push(s);
302	
303	  const sessions: ParsedSession[] = [];
304	  for (const [id, group] of bySession) {
305	    group.sort((a, b) => a.start.localeCompare(b.start));
306	    const first = group[0]!;
307	    const withTokens = group.filter((g) => g.tokens);
308	    const sum = (k: "in" | "out" | "cr" | "cw") => withTokens.reduce((n, g) => n + g.tokens![k], 0);
309	    const usageSources = new Set(withTokens.map((g) => g.usage_source));
310	    const modelSlice = group.find((g) => g.model);
311	    const model = modelSlice?.model ?? "unknown";
312	    // commit: earliest-created checkpoint of this session that has a trailer-linked commit
313	    const commit = group.map((g) => commits.get(g.checkpoint_id)).find(Boolean) ?? null;
314	    sessions.push({
315	      id,
316	      repo: repoName,
317	      checkpoint_id: first.checkpoint_id,
318	      harness: first.agent,
319	      model,
320	      rules_hash: group.find((g) => g.rules_hash)?.rules_hash ?? null,
321	      setup_id: null,
322	      tokens_in: sum("in"),
323	      tokens_out: sum("out"),
324	      cache_read: sum("cr"),
325	      cache_write: sum("cw"),
326	      cost_usd: null,
327	      n_user_prompts: group.reduce((n, g) => n + g.prompts.length, 0),
328	      first_prompt: group.find((g) => g.prompts.length)?.prompts[0] ?? "",
329	      commit_sha: commit,
330	      started_at: group.map((g) => g.start).filter(Boolean).sort()[0] ?? "",
331	      ended_at: group.map((g) => g.end).filter(Boolean).sort().at(-1) ?? "",
332	      files: [...new Set(group.flatMap((g) => g.files))].sort(),
333	      entire_url: gh ? `https://entire.io/gh/${gh.owner}/${gh.name}/session/${id}` : null,
334	      source: first.source,
335	      usage_source: usageSources.size === 0 ? "none" : usageSources.size === 1 ? [...usageSources][0]! : "transcript",
336	      model_source: !modelSlice ? "none" : modelSlice.model_from_meta ? "metadata" : "transcript",
337	    });
338	  }
339	  return sessions.sort((a, b) => a.started_at.localeCompare(b.started_at) || a.id.localeCompare(b.id));
340	}
